# Contenido didáctico original; casos y actividades elaborados para el campus.
DATA=[
 dict(title='Identificación de gemas',goal='El estudiante diferencia una descripción visual de una identificación sustentada y organiza una ficha básica de observación.',
 concepts=[('La identificación comienza con preguntas','La gemología estudia materiales usados como gemas, sus propiedades y su reconocimiento. Una especie mineral se define por composición y estructura; una variedad distingue un subconjunto, por ejemplo por color. La esmeralda es una variedad del berilo. El nombre comercial de una piedra no constituye una identificación.'),('Observar, medir y contrastar','La observación registra color, transparencia, forma, talla y estado superficial. La medición incorpora masa y dimensiones; cuando procede, se añaden resultados ópticos y examen microscópico. La conclusión debe concordar con varias evidencias. Si faltan pruebas, corresponde registrar “identificación pendiente”, no completar el dato por intuición.'),('Identidad, origen y tratamiento','Son preguntas diferentes: qué material es, cómo se formó y qué modificaciones recibió. Un aspecto verde no confirma una esmeralda; una fotografía tampoco permite afirmar procedencia colombiana. Las pruebas básicas orientan y algunos casos requieren análisis de laboratorio [1, 2].')],
 rows=[('Observación','Color, transparencia, talla y daños visibles.'),('Medición','Masa en ct; dimensiones en mm; método empleado.'),('Interpretación','Hipótesis compatibles y pruebas aún necesarias.'),('Conclusión','Identificación sustentada o resultado no concluyente.')],
 case='Caso didáctico: una piedra verde rectangular presenta una fractura visible. Solo se dispone de una fotografía. La ficha correcta describe color, forma y fractura; deja especie, origen y tratamiento como no determinados. La forma de corte no cambia esa conclusión.',
 task='El estudiante selecciona una pieza de práctica o una fotografía identificada como tal y redacta una ficha con código, fecha, observaciones, datos medidos y límites. Se separan en dos columnas los hechos observados y las interpretaciones. No se realizan rayados, golpes ni pruebas con calor.',
 questions=['¿El color verde demuestra que una piedra es esmeralda?','¿Qué diferencia existe entre observación e interpretación?','¿Qué debe escribirse cuando no hay pruebas suficientes?'],answers='1. No; el color es una observación compartida por varios materiales. 2. Observar describe un dato; interpretar propone su significado. 3. Identificación pendiente o no concluyente, junto con las pruebas que faltan.',refs=['identity','emerald']),
 dict(title='Propiedades físicas y ópticas',goal='El estudiante distingue dureza, tenacidad, densidad y propiedades ópticas, y emplea unidades sin confundirlas.',
 concepts=[('Propiedades físicas','La dureza expresa resistencia al rayado; la tenacidad, resistencia a romperse o astillarse. No son equivalentes. La escala de Mohs es relativa y sus intervalos no son uniformes. Una gema dura puede presentar fracturas. La esmeralda se sitúa entre 7,5 y 8 en Mohs y requiere cuidado frente a golpes y calor [1].'),('La luz como fuente de información','El índice de refracción describe la propagación de la luz en un material. La birrefringencia es la diferencia entre índices principales en materiales ópticamente anisótropos. El pleocroísmo es una variación de color con la dirección de observación bajo condiciones adecuadas. El brillo superficial y la transparencia describen otros aspectos; no sustituyen las mediciones.'),('Masa y densidad','Un quilate métrico equivale a 0,2 g. La masa en quilates no indica tamaño ni calidad por sí sola. La densidad relaciona masa y volumen; la gravedad específica compara la densidad de la muestra con la del agua y no lleva unidades. Las mediciones hidrostáticas exigen una muestra apropiada, equipo y control de errores [2].')],
 rows=[('Magnitud','Interpretación práctica'),('Masa: 1,50 ct','Equivale a 0,30 g; no identifica la especie.'),('Dimensiones: mm','Largo, ancho y profundidad registrados por separado.'),('Índice de refracción','Resultado sin unidad; depende del material y de las condiciones de medida.'),('Dureza de Mohs','Resistencia relativa al rayado; no equivale a tenacidad.')],
 case='Ejemplo resuelto: una gema tiene 0,48 g. Su masa es 0,48 / 0,2 = 2,40 ct. Dos piedras de esa misma masa pueden tener tamaños diferentes por su densidad y por la distribución del material en la talla.',
 task='El estudiante convierte 0,16 g y 0,70 g a quilates, y 3,25 ct a gramos. Después redacta una explicación de por qué una esmeralda no debe someterse a una prueba de rayado para demostrar su dureza. Las propiedades se consultan; no se dañan piezas de joyería.',
 questions=['¿Dureza alta significa resistencia absoluta a golpes?','¿Cuántos quilates corresponden a 0,16 g?','¿Cuántos gramos corresponden a 3,25 ct?'],answers='1. No; dureza y tenacidad son propiedades distintas. 2. 0,80 ct. 3. 0,65 g. Resultado adicional de la actividad: 0,70 g = 3,50 ct.',refs=['care','analysis']),
 dict(title='Instrumentos gemológicos',goal='El estudiante relaciona cada instrumento con la pregunta que ayuda a responder y registra los límites de su uso.',
 concepts=[('Observación ampliada','La lupa permite una primera inspección de superficie, aristas e inclusiones visibles. El microscopio ofrece mayor detalle y diferentes condiciones de iluminación. Ninguno convierte automáticamente una inclusión observada por un principiante en prueba de origen. Conviene describir forma, ubicación y aumento antes de interpretar.'),('Instrumentos ópticos','El refractómetro ayuda a medir índices de refracción; el polariscopio estudia la respuesta a la luz polarizada; el dicroscopio permite comparar colores de polarización y el espectroscopio muestra características de absorción. Estos instrumentos forman parte del examen gemológico convencional; los laboratorios pueden añadir espectroscopía y análisis químicos [1, 2].'),('Una medición debe poder revisarse','Se anota instrumento, identificación de la muestra, fecha, configuración, calibración o comprobación previa y resultado. La ausencia de un rasgo visible no siempre demuestra su inexistencia. El montaje en una joya, las superficies curvas y el estado de conservación pueden limitar determinadas pruebas.')],
 rows=[('Instrumento','Registro básico esperado'),('Balanza y calibre','Masa, dimensiones, unidad y resolución.'),('Lupa o microscopio','Aumento, iluminación, rasgos y posición.'),('Refractómetro','Lecturas obtenidas y condiciones de medición.'),('Polariscopio / dicroscopio','Respuesta observada, orientación y limitaciones.')],
 case='Caso didáctico: un estudiante registra “se observan líneas internas a 10 aumentos”. El dato es útil, pero no demuestra por sí solo crecimiento natural o sintético. Se requiere describir las líneas, contrastarlas con otros rasgos y decidir qué pruebas adicionales permitirían discriminar hipótesis.',
 task='El estudiante diseña una hoja de laboratorio con una fila por instrumento: pregunta, configuración, resultado y limitación. Si no hay equipos disponibles, completa la columna de pregunta y marca las mediciones como no realizadas. Los líquidos de contacto y fuentes UV solo se manejan según instrucciones del fabricante y bajo supervisión.',
 questions=['¿Qué instrumento ayuda a obtener el índice de refracción?','¿Por qué se registra el aumento utilizado?','¿Una sola observación confirma siempre naturalidad?'],answers='1. El refractómetro. 2. Permite interpretar y repetir la observación. 3. No; se requiere evidencia convergente y, cuando corresponde, análisis especializado.',refs=['identity','analysis']),
 dict(title='Diamantes, rubíes, zafiros, esmeraldas y perlas',goal='El estudiante reconoce diferencias entre cinco grupos gemológicos y evita aplicar un mismo criterio de calidad a todos.',
 concepts=[('Un nombre no es un color aislado','El diamante es carbono cristalino. Rubí y zafiro pertenecen al corindón: el rubí es la variedad roja, mientras que el zafiro puede presentar varios colores. La esmeralda pertenece al berilo. Las perlas se forman en moluscos; pueden ser naturales o cultivadas. Una perla cultivada no equivale a una imitación.'),('Criterios de descripción','En diamantes se emplean las 4C: color, claridad, talla y masa en quilates [1]. En gemas de color también se describen color, transparencia, talla y masa, pero las escalas no se trasladan sin adaptación. En perlas se consideran tamaño, forma, color, lustre, superficie, nácar y, en conjuntos, correspondencia entre piezas [2].'),('Una comparación responsable','Las fichas deben indicar especie o material, condición natural o de laboratorio cuando esté determinada, tratamientos conocidos y límites del análisis. No es suficiente comparar dos piezas únicamente por tamaño, una fotografía o el nombre de la localidad declarada.')],
 rows=[('Material','Punto de partida para su estudio'),('Diamante','4C e identificación de formación natural o de laboratorio.'),('Rubí y zafiro','Corindón; color y tratamientos requieren atención.'),('Esmeralda','Berilo; color, inclusiones y posibles rellenos de fisuras.'),('Perla','Tipo, lustre, superficie, nácar y demás factores propios.')],
 case='Caso didáctico: se comparan una perla cultivada y una esfera de vidrio recubierta. Ambas pueden parecer blancas y brillantes, pero su semejanza no las convierte en el mismo material. La ficha de la primera debe indicar cultivada; la segunda debe describirse como imitación cuando esa identificación esté sustentada.',
 task='El estudiante prepara cinco fichas, una por cada grupo. Cada ficha contiene material o especie, un criterio de calidad, una posible confusión y la prueba o fuente que permitiría resolverla. Si solo se dispone de imágenes, se diferencia lo visible de lo que todavía requiere análisis.',
 questions=['¿Rubí y zafiro pertenecen a la misma especie?','¿Una perla cultivada es necesariamente una imitación?','¿Las 4C equivalen al sistema descriptivo de las perlas?'],answers='1. Sí, ambos pertenecen al corindón. 2. No; cultivada describe intervención humana en su formación en el molusco. 3. No; las perlas tienen factores específicos.',refs=['diamond','pearl','emerald']),
 dict(title='Gemas naturales, sintéticas, tratadas e imitaciones',goal='El estudiante utiliza estas categorías sin confundir formación, modificaciones y semejanza visual.',
 concepts=[('Dos preguntas independientes','Natural y sintética describen la formación. Una gema sintética o creada en laboratorio posee esencialmente la composición y propiedades de su equivalente natural, pero se ha producido artificialmente. Tratada describe una modificación posterior. Una gema natural puede estar tratada; estas dos palabras no se excluyen [1, 2].'),('Imitación y material compuesto','Una imitación reproduce la apariencia de otra gema sin tener necesariamente su composición o estructura. El vidrio verde puede imitar esmeralda. Un material compuesto reúne partes; no debe describirse como una pieza homogénea si se sabe que contiene capas o elementos unidos.'),('Tratamientos y comunicación','Calor, tinción, impregnación y relleno de fracturas son ejemplos de tratamientos. Su detección puede requerir equipo especializado. Debe registrarse exactamente lo determinado y comunicar cuidados pertinentes. “No se detectó evidencia” tiene un alcance diferente a afirmar que ningún tratamiento es posible [2].')],
 rows=[('Descripción','Qué comunica'),('Esmeralda natural tratada','Formación natural y modificación posterior declarada.'),('Esmeralda sintética','Material producido en laboratorio; no es vidrio verde.'),('Imitación de esmeralda','Semejanza visual; el material real debe identificarse.'),('Resultado no concluyente','No se dispone de evidencia suficiente para clasificar.')],
 case='Caso didáctico: un informe identifica una esmeralda natural con relleno de fisuras. La descripción “esmeralda sintética” sería incorrecta, porque confunde tratamiento con formación. La descripción adecuada conserva ambos datos del informe y no inventa el tipo de relleno si este no se determinó.',
 task='El estudiante redacta descripciones para tres casos ficticios: vidrio que imita esmeralda, esmeralda creada en laboratorio y esmeralda natural con tratamiento confirmado. Cada descripción diferencia material, formación y modificación. Se evita añadir afirmaciones como “sin tratamiento” cuando no hay evidencia.',
 questions=['¿Una gema tratada es siempre sintética?','¿Una imitación debe tener la composición de la gema imitada?','¿Qué dato se conserva de un informe de tratamiento?'],answers='1. No. 2. No; la imitación se basa en la apariencia. 3. La descripción y alcance exactos del resultado, sin convertirlos en una garantía más amplia.',refs=['emerald','treatment']),
 dict(title='Tasación y valoración',goal='El estudiante organiza los datos necesarios para una valoración y distingue identificación, calidad y estimación económica.',
 concepts=[('Identificar antes de comparar','La identificación responde qué material se estudia; la descripción de calidad caracteriza la pieza; la valoración estima un importe para una finalidad y una fecha. Una cifra sin moneda, fecha, mercado y estado del objeto no es una conclusión reproducible. Esta guía no ofrece cotizaciones ni una tasación comercial.'),('Factores que deben documentarse','En gemas de color se estudian tono, matiz, saturación y distribución del color, además de transparencia, talla, masa y tratamientos [1]. En esmeraldas, el nivel de relleno de fisuras informado por un laboratorio no debe interpretarse como una calificación global de claridad [2]. La procedencia declarada debe distinguirse de la determinada por análisis.'),('Comparables, no promesas','La comparación necesita piezas suficientemente semejantes y fuentes fechadas. Precio anunciado, precio de una operación y valor de reposición son conceptos distintos. El estudiante debe indicar si las diferencias de calidad, tratamiento, tamaño o documentación impiden una comparación directa. No existe un multiplicador universal para toda esmeralda.')],
 rows=[('Dato de la ficha','Razón para registrarlo'),('Finalidad y fecha','Definen el contexto de la estimación.'),('Identidad y tratamientos','Permiten seleccionar comparables pertinentes.'),('Calidad y dimensiones','Explican diferencias entre piezas.'),('Fuente, moneda y mercado','Permiten revisar el cálculo y su alcance.')],
 case='Ejercicio exclusivamente aritmético: una pieza ficticia pesa 1,20 ct y se supone, solo para practicar, un importe de 100 unidades monetarias por ct. El total del ejercicio es 120 unidades monetarias. El cálculo no demuestra que ese importe por ct sea adecuado ni representa un precio real.',
 task='El estudiante completa una ficha ficticia con finalidad, fecha, identidad, tratamientos, masa, descripción y tres campos de comparables. Si no se dispone de datos verificables, se escribe “sin estimación económica”. La calidad del ejercicio se evalúa por la trazabilidad de los datos, no por producir una cifra.',
 questions=['¿Un informe de identificación determina automáticamente un precio?','¿Dos piedras del mismo peso tienen necesariamente el mismo valor?','¿Qué resultado produce el ejemplo aritmético?'],answers='1. No; identificación y valoración responden preguntas distintas. 2. No; calidad, tratamiento y contexto también influyen. 3. 120 unidades monetarias ficticias, sin validez comercial.',refs=['value','quality']),
 dict(title='Esmeraldas colombianas',goal='El estudiante distingue características de la esmeralda, indicios de procedencia y conclusiones de laboratorio.',
 concepts=[('La esmeralda y su procedencia','La esmeralda es una variedad verde del berilo. En Colombia se reconocen localidades como Muzo, Chivor y Coscuez. La procedencia es un dato geográfico que debe sustentarse, no una clasificación que pueda deducirse solo del tono verde o de la reputación de un vendedor.'),('Inclusiones como evidencia','Algunas esmeraldas presentan inclusiones con líquido, gas y un sólido. Aunque ciertas inclusiones trifásicas se asocian a material colombiano, también se han documentado rasgos semejantes en otras procedencias. El estudio de origen combina microscopía, espectroscopía y, cuando se requiere, datos de elementos traza. Una sola inclusión no autoriza una conclusión general [1, 2].'),('Estado y cuidados','Las fisuras y sus posibles rellenos influyen en la apariencia y en los cuidados. Deben evitarse golpes, calor y limpieza por vapor o ultrasonidos cuando existe riesgo de daño. La limpieza suave con agua tibia jabonosa es una opción descrita para esmeraldas; una pieza montada o dañada requiere revisar también su estado y engaste [3].')],
 rows=[('Afirmación','Evidencia que debe solicitarse'),('“Esmeralda”','Identificación del material.'),('“Natural”','Resultado sobre formación; no basta el aspecto.'),('“De Colombia”','Conclusión de origen, con alcance y limitaciones.'),('“Sin tratamiento”','Análisis pertinente; no se deduce de una fotografía.')],
 case='Caso didáctico: una piedra tiene inclusiones trifásicas y el vendedor afirma que procede de Muzo. La ficha registra lo observado y la procedencia declarada por separado. Sin un análisis suficiente no debe convertirse esa declaración en origen confirmado ni asignarse una mina concreta.',
 task='El estudiante redacta dos párrafos: uno describe observaciones y otro enumera pruebas faltantes para estudiar origen y tratamientos. Después elabora una etiqueta de conservación que mencione protección frente a golpes, precaución con calor y consulta profesional ante fisuras o engastes dañados.',
 questions=['¿Una inclusión trifásica demuestra siempre origen colombiano?','¿Qué diferencia hay entre origen declarado y determinado?','¿Es prudente limpiar una esmeralda fisurada con ultrasonidos?'],answers='1. No; hay rasgos semejantes en otras procedencias. 2. El primero es una afirmación recibida; el segundo se sustenta en análisis. 3. No, por el riesgo para fisuras y rellenos.',refs=['origin','inclusions','care']),
 dict(title='Bonos adicionales: cuaderno de práctica',goal='El estudiante integra lo aprendido en una bitácora y una ficha final de estudio, sin presentar ejercicios como informes de laboratorio.',
 concepts=[('Una bitácora que conserva la evidencia','Cada muestra recibe un código estable. Se anotan fecha, procedencia declarada, fotografías, observaciones y mediciones. Los datos no disponibles se marcan como tales. Una modificación posterior debe poder distinguirse del registro inicial; así se evita convertir una suposición repetida en un supuesto hecho.'),('Fotografía para documentar','Una secuencia didáctica útil contiene una vista general, una vista lateral y un detalle. El fondo neutro y la iluminación constante facilitan comparar imágenes. Una referencia de escala ayuda a interpretar dimensiones, pero no reemplaza un calibre. El color registrado por una cámara no acredita identidad, tratamiento ni procedencia.'),('Lectura crítica de informes','Conviene revisar identificación de la pieza, masa, dimensiones, fecha, resultados y alcance. Los laboratorios combinan técnicas convencionales y avanzadas según el caso [1]. Antes de reproducir una conclusión se comprueba que el documento corresponde a la muestra y que no se omiten limitaciones.')],
 rows=[('Plantilla de bitácora','Contenido esperado'),('Código / fecha / responsable','Identificadores del ejercicio y de la muestra.'),('Datos observados / medidos','Descripción separada de hipótesis; unidades.'),('Pruebas / resultados','Método, condiciones y mediciones no realizadas.'),('Conclusión / pendientes','Alcance, fuentes y siguiente paso propuesto.')],
 case='Ejemplo de registro: “Muestra A-01; imagen de práctica; color verde; talla rectangular; masa no medida; identidad pendiente”. Este registro es más útil que “esmeralda colombiana de alta calidad” cuando no se dispone de pruebas. La precisión incluye reconocer lo desconocido.',
 task='Producto integrador: el estudiante entrega una ficha de una página con código, dos imágenes propias o autorizadas, cinco observaciones, datos medidos o pendientes, dos hipótesis y una conclusión limitada a la evidencia. Añade dos referencias y una nota de cuidados cuando corresponda. Si solo hay fotografías, se identifica expresamente esa limitación.',
 questions=['¿Qué se escribe cuando una medición no se realizó?','¿Una foto sustituye un informe gemológico?','¿Qué criterios sirven para revisar la ficha final?'],answers='1. No medida o no realizada. 2. No. 3. Coherencia entre evidencia y conclusión, claridad de unidades, identificación de fuentes y reconocimiento de límites.',refs=['analysis','care']),
]
styles=getSampleStyleSheet()
