def footer(c,d):
 c.setStrokeColor(colors.HexColor('#c5a453'));c.line(42,42,A4[0]-42,42)
 c.setFont('Guide',8);c.setFillColor(colors.HexColor('#526760'))
 c.drawString(42,28,'Campus de Gemología | Guía básica de estudio | Noviembre de 2026')
 c.drawRightString(A4[0]-42,28,str(d.page))
def table(rows):
 data=[[p(escape(a),'SmallG'),p(escape(b),'SmallG')] for a,b in rows]
 t=Table(data,colWidths=[155,356],hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#f0f7f3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#d1dfd8'))]))
 return t
for i,d in enumerate(DATA,1):
 filename=f'modulo-{i:02}-guia-basica.pdf'
 story=[p(f'MÓDULO {i:02} / 08 · DOCUMENTACIÓN BÁSICA','SmallG'),p(d['title'],'TitleG'),p('<b>Objetivo.</b> '+d['goal'])]
 for h,t in d['concepts']:story +=[p(h,'SubG'),p(t)]
 story +=[Spacer(1,8),table(d['rows']),PageBreak(),p(f'MÓDULO {i:02} · APLICACIÓN Y REPASO','SmallG'),p('Del concepto a la práctica','TitleG'),p('Ejemplo aplicado','SubG'),p(d['case']),p('Actividad de estudio','SubG'),p(d['task']),p('Autoevaluación','SubG')]
 for j,q in enumerate(d['questions'],1):story.append(p(f'{j}. {q}'))
 story +=[p('Respuestas orientadoras','SubG'),p(d['answers']),p('Referencias y consulta','SubG')]
